+func partialEvents(events ...map[string]any) *verificationLog {
+	return &verificationLog{events: events}
+}
+
+func TestPartialRetainsCompletedResults(t *testing.T) {
+	cfg := &project.Config{
+		Setup:  []string{"make deps", "make tools"},
+		Checks: []project.Check{{Name: "compile", Run: "go build ./..."}, {Name: "vet", Run: "go vet ./..."}},
+	}
+	intent := &project.Intent{Model: &project.ModelSpec{None: true}}
+	log := partialEvents(
+		map[string]any{"event": "command", "name": "setup-1", "command": "make deps"},
+		map[string]any{"event": "command", "name": "setup-2", "command": "make tools"},
+		map[string]any{"event": "command_result", "name": "setup-2", "status": 3, "output": "tools failed\n"},
+		map[string]any{"event": "command_result", "name": "setup-1", "status": 0, "output": "deps ok\n"},
+		map[string]any{"event": "command", "name": "acceptance", "command": "run acceptance"},
+		map[string]any{"event": "command_result", "name": "acceptance", "status": 0, "output": "acceptance ok\n"},
+		map[string]any{"event": "command", "name": "vet", "command": "go vet ./..."},
+		map[string]any{"event": "command", "name": "compile", "command": "go build ./..."},
+		map[string]any{"event": "command_result", "name": "vet", "status": 2, "output": "vet complaint\n"},
+		map[string]any{"event": "command_result", "name": "compile", "status": 0, "output": "compiled\n"},
+	)
+	want := verify.Pass{
+		N: 1, Tree: "tree-1", Model: verify.ModelNone,
+		Setup: []verify.CommandResult{
+			{Name: "setup-1", Command: "make deps", Status: 0, Output: "deps ok\n"},
+			{Name: "setup-2", Command: "make tools", Status: 3, Output: "tools failed\n"},
+		},
+		Checks: []verify.CommandResult{
+			{Name: "compile", Command: "go build ./...", Status: 0, Output: "compiled\n"},
+			{Name: "vet", Command: "go vet ./...", Status: 2, Output: "vet complaint\n"},
+		},
+		NotRun: []string{},
+	}
+	if got := log.partial("tree-1", cfg, intent); !reflect.DeepEqual(got, want) {
+		t.Fatalf("partial = %+v\nwant %+v", got, want)
+	}
+}
+
+func TestPartialListsMissingWorkWhenModelRequired(t *testing.T) {
+	cfg := &project.Config{
+		Setup:  []string{"make deps", "make tools"},
+		Checks: []project.Check{{Name: "compile", Run: "go build ./..."}, {Name: "vet", Run: "go vet ./..."}},
+	}
+	intent := &project.Intent{Model: &project.ModelSpec{Path: ".kogen/intents/x/model.qnt"}}
+	log := partialEvents(
+		map[string]any{"event": "command", "name": "setup-1", "command": "make deps"},
+		map[string]any{"event": "command_result", "name": "setup-1", "status": 0, "output": "deps ok\n"},
+		map[string]any{"event": "command", "name": "setup-2", "command": "make tools"},
+		map[string]any{"event": "command", "name": "vet", "command": "go vet ./..."},
+		map[string]any{"event": "command_result", "name": "vet", "status": 1, "output": "vet red\n"},
+	)
+	want := verify.Pass{
+		N: 1, Tree: "tree-2", Model: verify.ModelNotRun,
+		Setup:  []verify.CommandResult{{Name: "setup-1", Command: "make deps", Status: 0, Output: "deps ok\n"}},
+		Checks: []verify.CommandResult{{Name: "vet", Command: "go vet ./...", Status: 1, Output: "vet red\n"}},
+		NotRun: []string{"setup-2", "acceptance", "model", "compile"},
+	}
+	if got := log.partial("tree-2", cfg, intent); !reflect.DeepEqual(got, want) {
+		t.Fatalf("partial = %+v\nwant %+v", got, want)
+	}
+}
