+func TestPartialWithoutRequiredModel(t *testing.T) {
+	cfg := &project.Config{Setup: []string{"make deps"}, Checks: []project.Check{{Name: "compile", Run: "go build ./..."}}}
+	for _, intent := range []*project.Intent{{Model: &project.ModelSpec{None: true}}, {}} {
+		want := verify.Pass{
+			N: 1, Tree: "tree-3", Model: verify.ModelNone,
+			Setup: []verify.CommandResult{}, Checks: []verify.CommandResult{},
+			NotRun: []string{"setup-1", "acceptance", "compile"},
+		}
+		if got := (&verificationLog{}).partial("tree-3", cfg, intent); !reflect.DeepEqual(got, want) {
+			t.Fatalf("partial = %+v\nwant %+v", got, want)
+		}
+	}
+}

